/**
 * IntegrationErrorSchema
 *
 * Error response body carrying the stable code and optional provider context.
 */
export type IntegrationErrorSchema = {
    /**
     * Detail
     */
    detail: string;
    code: IntegrationErrorCode;
    /**
     * Provider Message
     */
    provider_message?: string | null;
};

